// Hit-test the pixels, not the destination
final class InteractiveContainer: UIView {
  override func hitTest(_ point: CGPoint, with event: UIEvent?) -> UIView? {
    // presentation() walks the on-screen copy of the whole subtree
    guard let hit = layer.presentation()?.hitTest(point),
          let view = hit.model().delegate as? UIView,   // back to the real layer, then its view
          view.isUserInteractionEnabled else {
      return super.hitTest(point, with: event)
    }
    return view
  }
}

// Or take the animation over instead of fighting its geometry
private var animator: UIViewPropertyAnimator?

@objc func handleTouch() {
  // pauseAnimation() writes the current interpolated values back into the model layer,
  // so frame, hit testing and what the user sees line up again
  animator?.pauseAnimation()
  let grabbedAt = animator?.fractionComplete ?? 0
  print("grabbed at \(grabbedAt)")
}

