final class RingView: UIView {
  private let ring = CAShapeLayer()

  override func layoutSubviews() {
    super.layoutSubviews()
    // The trap: this sublayer has no delegate, so every rotation slides it into place
    ring.frame = bounds
    ring.path = UIBezierPath(ovalIn: bounds.insetBy(dx: 4, dy: 4)).cgPath
  }

  private func silence() {
    // Answer the lookup at step 2, once, instead of wrapping every assignment
    ring.actions = ["position": NSNull(), "bounds": NSNull(), "path": NSNull()]
  }
}

// Or answer it at step 4 for a whole layer class
final class SnappyLayer: CAGradientLayer {
  override func action(forKey event: String) -> CAAction? {
    // nil continues the search; NSNull ends it and kills the implicit animation
    ["position", "bounds"].contains(event) ? NSNull() : super.action(forKey: event)
  }
}

// One property, no animation: stop the lookup before it starts
CATransaction.begin()
CATransaction.setDisableActions(true)
gradient.frame = bounds              // committed as a plain value change
CATransaction.commit()

// Not the same thing: an animation is still created, it just takes no time —
// and it replaces the move that was already running on this key
CATransaction.begin()
CATransaction.setAnimationDuration(0)
gradient.frame = bounds              // an in-flight frame animation dies here
CATransaction.commit()

// Unbalanced begin/commit is what makes the *next* screen animate strangely
func reposition(to path: CGPath?) {
  CATransaction.begin()
  defer { CATransaction.commit() }   // survives every early return
  CATransaction.setDisableActions(true)
  guard let path else { return }
  shape.path = path
}

// Completion fires once for the transaction, so set it before the changes
CATransaction.begin()
CATransaction.setCompletionBlock { [weak self] in
  self?.overlay.removeFromSuperlayer()
}
CATransaction.setAnimationDuration(0.4)
CATransaction.setAnimationTimingFunction(CAMediaTimingFunction(name: .easeOut))
overlay.opacity = 0
overlay.transform = CATransform3DMakeScale(1.4, 1.4, 1)
CATransaction.commit()

// Free: one commit, then the render server interpolates without waking your process
UIView.animate(withDuration: 0.4) {
  card.transform = CGAffineTransform(scaleX: 1.1, y: 1.1).rotated(by: .pi / 30)
  card.alpha = 0.6
}

// Expensive: a shadow with no path is recomputed from the alpha channel every frame
card.layer.shadowOpacity = 0.3
card.layer.shadowRadius = 12
// Fix — hand the compositor the silhouette up front
card.layer.shadowPath = UIBezierPath(roundedRect: card.bounds, cornerRadius: 16).cgPath

// Expensive: rounding plus clipping forces an offscreen pass while the card scales
card.layer.cornerRadius = 16
card.layer.masksToBounds = true
// Cheaper when the content allows it: pre-rounded opaque content, no clipping
imageView.image = preRoundedImage
imageView.isOpaque = true
card.layer.masksToBounds = false

// shouldRasterize caches a bitmap — a win only while the content holds still
snapshot.layer.shouldRasterize = true
snapshot.layer.rasterizationScale = snapshot.layer.contentsScale  // else the cache is blurry
// ...and a lie the moment it scales: the cache misses on every frame
UIView.animate(withDuration: 0.4) {
  snapshot.transform = CGAffineTransform(scaleX: 2, y: 2)
}

final class SheetInteraction {
  private var animator: UIViewPropertyAnimator?
  private let sheet: UIView
  private var travel: CGFloat { sheet.bounds.height }

  @objc func handle(_ pan: UIPanGestureRecognizer) {
    switch pan.state {
    case .began:
      let animator = UIViewPropertyAnimator(duration: 0.4, dampingRatio: 0.85) {
        self.sheet.transform = CGAffineTransform(translationX: 0, y: self.travel)
      }
      animator.scrubsLinearly = true   // sheet tracks the finger 1:1 while paused
      animator.startAnimation()
      animator.pauseAnimation()        // fractionComplete only bites once paused
      self.animator = animator

    case .changed:
      animator?.fractionComplete = pan.translation(in: sheet).y / travel

    case .ended, .cancelled:
      guard let animator else { return }
      let velocity = pan.velocity(in: sheet).y
      animator.isReversed = velocity < 0   // runs back to 0 and completes at .start
      let remaining = travel * (1 - animator.fractionComplete)
      let dy = remaining > 0 ? velocity / remaining : 0
      // The release supplies a fresh curve carrying the gesture's velocity
      animator.continueAnimation(
        withTimingParameters: UISpringTimingParameters(
          dampingRatio: 0.8, initialVelocity: CGVector(dx: 0, dy: dy)),
        durationFactor: 0.7)

    default:
      break
    }
  }

  func onFinish() {
    // Never assume .end — a reversed animator finishes at .start
    animator?.addCompletion { position in
      if position == .end { self.sheet.removeFromSuperview() }
    }
  }
}

final class DismissAnimator: NSObject, UIViewControllerAnimatedTransitioning {
  private weak var fromView: UIView?
  private let dimming = UIView()

  func transitionDuration(using c: UIViewControllerContextTransitioning?) -> TimeInterval { 0.35 }

  func animateTransition(using context: UIViewControllerContextTransitioning) {
    guard let from = context.view(forKey: .from) else {
      return context.completeTransition(false)
    }
    fromView = from
    let container = context.containerView
    if let to = context.view(forKey: .to) { container.insertSubview(to, at: 0) }

    UIView.animate(withDuration: transitionDuration(using: context)) {
      from.transform = CGAffineTransform(translationX: 0, y: container.bounds.height)
    } completion: { _ in
      // The real outcome — not `true`. A cancelled transition reported as finished
      // leaves UIKit convinced the screen changed, and the app frozen.
      context.completeTransition(!context.transitionWasCancelled)
    }
  }

  func animationEnded(_ transitionCompleted: Bool) {
    dimming.removeFromSuperview()                     // only what this animator invented
    if !transitionCompleted { fromView?.transform = .identity }
    fromView = nil
  }
}

final class DismissInteraction: UIPercentDrivenInteractiveTransition {
  var isDriving = false   // interactionControllerForDismissal returns nil unless this is true

  @objc func handle(_ pan: UIPanGestureRecognizer, presented: UIViewController) {
    let progress = min(max(pan.translation(in: pan.view).y / 300, 0), 1)
    switch pan.state {
    case .began:
      isDriving = true
      presented.dismiss(animated: true)
    case .changed:
      update(progress)
    default:
      progress > 0.4 && pan.state == .ended ? finish() : cancel()
      isDriving = false
    }
  }
}

final class SlideAnimator: NSObject, UIViewControllerAnimatedTransitioning {
  private let operation: UINavigationController.Operation
  init(operation: UINavigationController.Operation) { self.operation = operation }

  func transitionDuration(using c: UIViewControllerContextTransitioning?) -> TimeInterval { 0.32 }

  func animateTransition(using context: UIViewControllerContextTransitioning) {
    let container = context.containerView
    guard let toVC = context.viewController(forKey: .to),
          let toView = context.view(forKey: .to),   // nil if a presentation controller owns it
          let fromView = context.view(forKey: .from) else {
      return context.completeTransition(false)
    }

    // UIKit decides the destination rect — not just container bounds
    toView.frame = context.finalFrame(for: toVC)
    let sign: CGFloat = operation == .push ? 1 : -1
    toView.transform = CGAffineTransform(translationX: sign * container.bounds.width, y: 0)

    container.addSubview(toView)   // you add the incoming view; the outgoing one is here

    UIView.animate(withDuration: transitionDuration(using: context),
                   delay: 0, options: .curveEaseInOut) {
      toView.transform = .identity
      fromView.transform = CGAffineTransform(translationX: -sign * container.bounds.width / 3, y: 0)
    } completion: { _ in
      fromView.transform = .identity   // reused on the way back — hand it back clean
      // No removeFromSuperview() here: UIKit takes the loser off itself
      context.completeTransition(!context.transitionWasCancelled)
    }
  }
}

extension AppCoordinator: UINavigationControllerDelegate {
  func navigationController(_ nc: UINavigationController,
                            animationControllerFor operation: UINavigationController.Operation,
                            from: UIViewController,
                            to: UIViewController) -> UIViewControllerAnimatedTransitioning? {
    SlideAnimator(operation: operation)
  }
}

struct Inbox: View {
  @State private var showDetail = false
  @State private var items: [Item] = Item.samples

  var body: some View {
    VStack {
      // Wrong: a property change on a view that never leaves — the transition never runs
      Detail()
        .opacity(showDetail ? 1 : 0)
        .transition(.slide)

      // Right: the branch inserts and removes the view, so identity changes
      if showDetail {
        Detail()
          .transition(.asymmetric(
            insertion: .move(edge: .bottom).combined(with: .opacity),
            removal: .scale(scale: 0.9).combined(with: .opacity)))
      }

      ForEach(items) { item in
        Row(item: item)
          .transition(.move(edge: .leading))
          .onTapGesture { delete(item) }
      }

      Button("Toggle") { withAnimation(.bouncy) { showDetail.toggle() } }
    }
    // On the container: the inserted view does not exist yet to carry its own animation
    .animation(.snappy, value: showDetail)
  }

  private func delete(_ item: Item) {
    // The leaving row keeps rendering for the whole removal transition, so its body
    // must not index back into a model that no longer holds it
    withAnimation { items.removeAll { $0.id == item.id } }
  }
}

