struct CardGallery: View {
  @Namespace private var cards          // must outlive both sides of the pair
  @State private var expanded: String?
  private let ids = ["a", "b", "c", "d"]

  var body: some View {
    ZStack {
      LazyVGrid(columns: [GridItem(), GridItem()]) {
        ForEach(ids, id: \.self) { id in
          Color.teal
            // exactly one source at a time: the thumbnail yields when expanded
            .matchedGeometryEffect(id: id, in: cards, isSource: expanded != id)
            .frame(height: 120)
            .onTapGesture { withAnimation(.snappy) { expanded = id } }
        }
      }
      if let id = expanded {
        Color.teal
          .matchedGeometryEffect(id: id, in: cards, isSource: true)
          .frame(maxWidth: .infinity, maxHeight: 400)
          .onTapGesture { withAnimation(.snappy) { expanded = nil } }
      }
    }
  }
}

// Across a NavigationStack push there is no second view to match against,
// so the zoom transition is the supported equivalent.
struct Gallery: View {
  @Namespace private var photos

  var body: some View {
    NavigationStack {
      NavigationLink(value: photo) { Thumbnail(photo) }
        .matchedTransitionSource(id: photo.id, in: photos)
        .navigationDestination(for: Photo.self) { photo in
          DetailView(photo)
            .navigationTransition(.zoom(sourceID: photo.id, in: photos))
        }
    }
  }
}

struct Pose {
  var scale = 1.0
  var angle = Angle.zero
  var lift = 0.0
}

struct Badge: View {
  @State private var trigger = 0

  var body: some View {
    Image(systemName: "bell.fill")
      .keyframeAnimator(initialValue: Pose(), trigger: trigger) { view, pose in
        view.scaleEffect(pose.scale)
          .rotationEffect(pose.angle)
          .offset(y: pose.lift)
      } keyframes: { _ in
        // three tracks, three independent clocks running at the same time
        KeyframeTrack(\Pose.scale) {
          SpringKeyframe(1.4, duration: 0.15, spring: .bouncy)
          SpringKeyframe(1.0, duration: 0.45, spring: .snappy)
        }
        KeyframeTrack(\Pose.angle) {
          CubicKeyframe(.degrees(-18), duration: 0.2)
          CubicKeyframe(.degrees(14), duration: 0.2)
          CubicKeyframe(.zero, duration: 0.2)
        }
        KeyframeTrack(\Pose.lift) {
          MoveKeyframe(0)                  // hold, then join the others late
          LinearKeyframe(-8, duration: 0.25)
          LinearKeyframe(0, duration: 0.25)
        }
      }
      .onTapGesture { trigger += 1 }
  }
}

// Phases: one state after another, everything moving together.
// Perfect for a pulse, and unable to stagger scale against rotation.
struct Pulse: View {
  var body: some View {
    Circle()
      .phaseAnimator([1.0, 1.3]) { view, scale in
        view.scaleEffect(scale)
      } animation: { scale in
        scale > 1 ? .bouncy(duration: 0.4) : .smooth(duration: 0.6)
      }
  }
}

// Snaps: `end` is only an init argument, so there is nothing to interpolate.
struct WedgeThatSnaps: Shape {
  var end: Double
  func path(in rect: CGRect) -> Path { Wedge(end: end).path(in: rect) }
}

// Animates: animatableData is the channel SwiftUI writes into each frame.
struct Wedge: Shape {
  var end: Double                       // 0...1

  var animatableData: Double {
    get { end }
    set { end = newValue }
  }

  func path(in rect: CGRect) -> Path {
    var path = Path()
    let center = CGPoint(x: rect.midX, y: rect.midY)
    path.move(to: center)
    path.addArc(center: center,
                radius: rect.width / 2,
                startAngle: .degrees(-90),
                endAngle: .degrees(-90 + 360 * end),
                clockwise: false)
    return path
  }
}

// A number that counts instead of jumping: the modifier is the animatable thing.
struct CountingNumber: ViewModifier, Animatable {
  var value: Double

  var animatableData: Double {
    get { value }
    set { value = newValue }
  }

  func body(content: Content) -> some View {
    Text(value, format: .number.precision(.fractionLength(0)))
  }
}

extension View {
  func counting(to value: Double) -> some View {
    modifier(CountingNumber(value: value))
  }
}

