final class WaveformView: UIView {
  private var link: CADisplayLink?
  private var phase: CFTimeInterval = 0

  override func didMoveToWindow() {
    super.didMoveToWindow()
    if window == nil { stop() } else { start() }
  }

  private func start() {
    guard link == nil else { return }
    let link = CADisplayLink(target: self, selector: #selector(step))
    // a range, not a demand: the system may run this at 30 Hz to save power
    link.preferredFrameRateRange = CAFrameRateRange(minimum: 30,
                                                    maximum: 120,
                                                    preferred: 60)
    link.add(to: .main, forMode: .common)   // keeps firing while a scroll tracks
    self.link = link
  }

  private func stop() {
    link?.invalidate()      // the link retains self; without this the view leaks
    link = nil
  }

  @objc private func step(_ link: CADisplayLink) {
    // the real delta for this frame, whatever rate the system settled on
    let delta = link.targetTimestamp - link.timestamp
    phase += delta * 2
    setNeedsDisplay()
  }
}

