// Backing store: 320x320 points at 3x is ~3.7 MB per view, repainted on change.
final class RingViewCG: UIView {
  var progress: CGFloat = 0 { didSet { setNeedsDisplay() } }   // full CPU redraw

  override func draw(_ rect: CGRect) {
    let path = UIBezierPath(arcCenter: CGPoint(x: rect.midX, y: rect.midY),
                            radius: rect.width / 2 - 4,
                            startAngle: -.pi / 2,
                            endAngle: -.pi / 2 + 2 * .pi * progress,
                            clockwise: true)
    path.lineWidth = 8
    UIColor.systemTeal.setStroke()
    path.stroke()
  }
}

// No backing store, and progress becomes one animatable property.
final class RingView: UIView {
  override class var layerClass: AnyClass { CAShapeLayer.self }
  private var ring: CAShapeLayer { layer as! CAShapeLayer }

  override init(frame: CGRect) {
    super.init(frame: frame)
    ring.fillColor = nil
    ring.strokeColor = UIColor.systemTeal.cgColor
    ring.lineWidth = 8
    ring.lineCap = .round
    ring.strokeEnd = 0
  }

  required init?(coder: NSCoder) { fatalError("use init(frame:)") }

  override func layoutSubviews() {
    super.layoutSubviews()
    CATransaction.setDisableActions(true)      // geometry must not animate here
    ring.path = UIBezierPath(ovalIn: bounds.insetBy(dx: 4, dy: 4)).cgPath
  }

  func setProgress(_ value: CGFloat) {
    let animation = CABasicAnimation(keyPath: "strokeEnd")
    animation.fromValue = ring.presentation()?.strokeEnd ?? ring.strokeEnd
    animation.duration = 0.4
    ring.strokeEnd = value            // model layer first, then the animation
    ring.add(animation, forKey: "progress")
  }
}

// Wrong: the flick's velocity is discarded, so the spring starts from rest.
func endDragBad() {
  UIView.animate(withDuration: 0.4) { self.sheet.frame.origin.y = self.restingY }
}

// Right: normalise the gesture velocity against the distance still to travel.
func endDrag(_ recognizer: UIPanGestureRecognizer) {
  let current = sheet.frame.origin.y
  let target = isDismissing ? view.bounds.height : restingY
  let distance = target - current
  let velocity = recognizer.velocity(in: view).y

  // initialVelocity is per unit of remaining distance, not points per second
  let unitVelocity = distance == 0 ? 0 : velocity / distance
  let timing = UISpringTimingParameters(
    dampingRatio: 0.8,
    initialVelocity: CGVector(dx: 0, dy: unitVelocity))

  let animator = UIViewPropertyAnimator(duration: 0.5, timingParameters: timing)
  animator.addAnimations { self.sheet.frame.origin.y = target }
  animator.startAnimation()
}

