private let log = OSLog(subsystem: "com.example.feed", category: .pointsOfInterest)
private let signposter = OSSignposter(logHandle: log)

// Commit-side hitch: the decode happens on the main thread as the frame commits.
func showCoverBad(_ data: Data) {
  UIView.animate(withDuration: 0.3) {
    self.cover.image = UIImage(data: data)   // decoded on first display
    self.cover.alpha = 1
  }
}

// Decode off the main thread and hand the render server a ready texture.
func showCover(_ data: Data) async {
  let state = signposter.beginInterval("cover-decode")
  let thumbnail = await UIImage(data: data)?
    .byPreparingThumbnail(ofSize: cover.bounds.size)
  signposter.endInterval("cover-decode", state)

  UIView.animate(withDuration: 0.3) {
    self.cover.image = thumbnail
    self.cover.alpha = 1
  }
}

