// On device, before Instruments is even open:
//   Settings > Developer > Metal HUD, or MTL_HUD_ENABLED=1 in the scheme.

final class HeaderView: UIView {
  private let curve = CAShapeLayer()

  static func path(for rect: CGRect) -> CGPath {
    let path = UIBezierPath()
    path.move(to: .zero)
    path.addLine(to: CGPoint(x: rect.maxX, y: 0))
    path.addQuadCurve(to: CGPoint(x: 0, y: rect.maxY),
                      controlPoint: CGPoint(x: rect.midX, y: rect.maxY * 1.4))
    path.close()
    return path.cgPath
  }

  override func layoutSubviews() {
    super.layoutSubviews()
    CATransaction.begin()
    CATransaction.setDisableActions(true)   // no accidental 0.25s implicit hop
    curve.frame = bounds
    curve.path = Self.path(for: bounds)
    CATransaction.commit()
  }

  // Called from the coordinator so the path shares the rotation's clock.
  func animatePath(to size: CGSize, duration: TimeInterval) {
    let animation = CABasicAnimation(keyPath: "path")
    animation.fromValue = curve.presentation()?.path ?? curve.path
    animation.toValue = Self.path(for: CGRect(origin: .zero, size: size))
    animation.duration = duration
    animation.timingFunction = CAMediaTimingFunction(name: .easeInEaseOut)
    curve.add(animation, forKey: "rotate")
  }
}

final class HeaderController: UIViewController {
  private let header = HeaderView()

  override func viewWillTransition(
    to size: CGSize,
    with coordinator: UIViewControllerTransitionCoordinator
  ) {
    super.viewWillTransition(to: size, with: coordinator)
    coordinator.animate(alongsideTransition: { context in
      self.header.animatePath(to: size, duration: context.transitionDuration)
    })
  }

  override func viewDidLoad() {
    super.viewDidLoad()
    // iOS 17 replaced traitCollectionDidChange(_:) with registered handlers.
    registerForTraitChanges([UITraitVerticalSizeClass.self]) { (self: Self, _) in
      self.header.setNeedsLayout()
    }
  }
}
